import{_ as i,C as r,o as n,c as a,a2 as s,E as o}from"./chunks/framework.CdvW4CUT.js";const v=JSON.parse('{"title":"Choisir sa mémoire","description":"","frontmatter":{"title":"Choisir sa mémoire"},"headers":[],"relativePath":"guide/vault.md","filePath":"guide/vault.md"}'),l={name:"guide/vault.md"};function u(d,e,c,m,p,h){const t=r("Capture");return n(),a("div",null,[e[0]||(e[0]=s('<h1 id="choisir-sa-memoire" tabindex="-1">Choisir sa mémoire <a class="header-anchor" href="#choisir-sa-memoire" aria-label="Permalink to &quot;Choisir sa mémoire&quot;">​</a></h1><p>La mémoire de Kessho est un <strong>dossier</strong> de fichiers Markdown sur votre disque. Vous le choisissez au premier lancement et vous pouvez le changer quand vous voulez. Cette page explique ce que vous pouvez choisir, et ce que le changement fait — et ne fait pas.</p><h2 id="ce-qu-est-la-memoire" tabindex="-1">Ce qu&#39;est la mémoire <a class="header-anchor" href="#ce-qu-est-la-memoire" aria-label="Permalink to &quot;Ce qu&#39;est la mémoire&quot;">​</a></h2><ul><li>Un dossier ordinaire, que vous pouvez copier, sauvegarder ou ouvrir avec d&#39;autres outils.</li><li>Des notes en Markdown, rangées par <a href="/guide/zones.html">zones</a>.</li><li>Compatible avec Obsidian : un dossier de notes Obsidian peut servir de mémoire. Kessho n&#39;en dépend pas, et n&#39;a pas besoin qu&#39;Obsidian soit installé.</li></ul><p>Vos agents et l&#39;application lisent le <strong>même</strong> dossier. Les assistants à qui Kessho est déclaré ne reçoivent aucun chemin : le serveur retrouve la mémoire tout seul, à partir de la configuration de l&#39;application. Changer de mémoire dans l&#39;application change donc aussi celle que voient vos agents.</p><h2 id="les-trois-facons-de-commencer" tabindex="-1">Les trois façons de commencer <a class="header-anchor" href="#les-trois-facons-de-commencer" aria-label="Permalink to &quot;Les trois façons de commencer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vous voulez…</th><th>Choisissez</th><th>Ce qui se passe</th></tr></thead><tbody><tr><td>Repartir de zéro</td><td><strong>Nouvelle mémoire Kessho</strong></td><td>Kessho propose un dossier qui n&#39;existe pas encore (« n&#39;existe pas encore »).</td></tr><tr><td>Utiliser des notes que vous avez déjà</td><td><strong>Dossier existant</strong></td><td>Kessho reconnaît les dossiers Obsidian ; il en compte les notes.</td></tr><tr><td>Reprendre une ancienne installation</td><td><strong>Installation précédente</strong></td><td>Kessho la propose quand il en détecte une sur votre poste.</td></tr></tbody></table><h2 id="choisir-sa-memoire-au-premier-lancement" tabindex="-1">Choisir sa mémoire au premier lancement <a class="header-anchor" href="#choisir-sa-memoire-au-premier-lancement" aria-label="Permalink to &quot;Choisir sa mémoire au premier lancement&quot;">​</a></h2>',8)),o(t,{name:"premier-lancement",alt:"Le premier lancement, étape 2 sur 5 : choisir le dossier qui sera la mémoire (dossier existant, installation précédente ou nouvelle mémoire)."}),e[1]||(e[1]=s('<ol><li>À l&#39;étape <strong>Emplacement</strong>, regardez les propositions. Chacune indique son type, son chemin et son nombre de notes (« 184 notes »).</li><li>Cliquez sur une proposition, ou saisissez un chemin dans <strong>Chemin de la mémoire</strong>, ou cliquez sur <strong>Parcourir…</strong> : le sélecteur « Choisir le dossier de la mémoire » s&#39;ouvre.</li><li>Si une proposition porte « lecture seule », Kessho n&#39;a pas pu y écrire lors d&#39;un essai : choisissez plutôt un autre emplacement.</li><li>Cliquez sur <strong>Suivant</strong>. À l&#39;étape suivante, <strong>Parcourir le dossier</strong> vous montre ce que Kessho y lit, sans rien enregistrer.</li><li>Au dernier écran, vérifiez <strong>Emplacement de la mémoire</strong>, puis cliquez sur <strong>Lancer Kessho</strong>.</li></ol><p>Le détail de chaque étape est dans <a href="/guide/first-run.html">Premier lancement</a>.</p><h2 id="changer-de-memoire-plus-tard" tabindex="-1">Changer de mémoire plus tard <a class="header-anchor" href="#changer-de-memoire-plus-tard" aria-label="Permalink to &quot;Changer de mémoire plus tard&quot;">​</a></h2><ol><li>Ouvrez <strong>Réglages</strong>, puis la section <strong>Mémoire</strong>.</li><li>La ligne <strong>Emplacement</strong> montre le dossier actuel. Cliquez sur <strong>Changer</strong>.</li><li>Choisissez un dossier dans le sélecteur.</li></ol><p>Le nouveau chemin est enregistré aussitôt. Si vous fermez le sélecteur sans choisir, rien n&#39;est écrit. Si l&#39;enregistrement échoue, l&#39;écran affiche « L&#39;enregistrement a échoué. » avec la cause, et l&#39;ancien chemin reste affiché.</p><p><strong>Changer ne déplace aucun fichier.</strong> Kessho se met à lire le dossier que vous avez choisi ; l&#39;ancien dossier reste tel quel, à sa place. Pour reprendre vos notes ailleurs, copiez le dossier vous-même avant de changer.</p><p>La section <strong>Mémoire</strong> montre aussi :</p><ul><li><strong>Contenu</strong> : le nombre de notes, de fichiers et la taille du dossier (par exemple « 184 notes · 190 fichiers · 2,1 Mo ») ;</li><li><strong>Sauvegarde</strong> : « Aucune — vos fichiers vous appartiennent », « Dépôt git local, sans distant » ou « Dépôt git synchronisé avec… » (voir <a href="/guide/sync.html">Synchronisation</a>) ;</li><li><strong>Ancienne installation</strong>, seulement si une ancienne installation est détectée et pas encore migrée.</li></ul><h2 id="si-une-installation-precedente-est-detectee" tabindex="-1">Si une installation précédente est détectée <a class="header-anchor" href="#si-une-installation-precedente-est-detectee" aria-label="Permalink to &quot;Si une installation précédente est détectée&quot;">​</a></h2><p>Un bandeau « Migration disponible » apparaît au-dessus des écrans. Il propose <strong>Lancer la Migration (1-Clic)</strong>, puis <strong>Vérifier la Migration</strong>. Cette migration reprend votre profil, l&#39;emplacement de la mémoire et les connecteurs de l&#39;ancienne installation.</p><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><ul><li>Voir ce que contient la mémoire : <a href="/guide/home.html">Accueil</a> et <a href="/guide/zones.html">Zones</a>.</li><li>Donner la mémoire à vos assistants : <a href="/guide/agents.html">Connecter ses agents</a>.</li></ul>',12))])}const q=i(l,[["render",u]]);export{v as __pageData,q as default};
